// server.js

const express = require('express');
const app = express();
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

app.use(cors());
app.use(express.json());

let todos = [];

app.get('/todos', (req, res) => {
  let filteredTodos = todos;
  if (req.query.completed !== undefined) {
    const completed = req.query.completed === 'true';
    filteredTodos = todos.filter(todo => todo.completed === completed);
  }
  res.json(filteredTodos);
});

app.get('/todos/:id', (req, res) => {
  const todo = todos.find(todo => todo.id === req.params.id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });
  res.json(todo);
});

app.post('/todos', (req, res) => {
  const { title } = req.body;
  if (!title || typeof title !== 'string' || title.length < 1 || title.length > 100) {
    return res.status(400).json({ error: 'Invalid title' });
  }
  const todo = {
    id: uuidv4(),
    title,
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  todos.push(todo);
  res.status(201).json(todo);
});

app.put('/todos/:id', (req, res) => {
  const todo = todos.find(todo => todo.id === req.params.id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });

  const { title, completed } = req.body;
  if (title !== undefined && (typeof title !== 'string' || title.length < 1 || title.length > 100)) {
    return res.status(400).json({ error: 'Invalid title' });
  }
  if (completed !== undefined && typeof completed !== 'boolean') {
    return res.status(400).json({ error: 'Invalid completed status' });
  }

  todo.title = title || todo.title;
  todo.completed = completed ?? todo.completed;
  todo.updatedAt = new Date().toISOString();
  res.json(todo);
});

app.delete('/todos/:id', (req, res) => {
  const index = todos.findIndex(todo => todo.id === req.params.id);
  if (index === -1) return res.status(404).json({ error: 'Todo not found' });
  todos.splice(index, 1);
  res.status(204).send();
});

module.exports = app;

// test.js

const request = require('supertest');
const app = require('./server');

describe('Todos API', () => {
  let todoId;

  it('should return an empty list of todos', async () => {
    const response = await request(app).get('/todos');
    expect(response.statusCode).toBe(200);
    expect(response.body).toEqual([]);
  });

  it('should create a new todo', async () => {
    const response = await request(app)
      .post('/todos')
      .send({ title: 'Test Todo' });
    expect(response.statusCode).toBe(201);
    expect(response.body).toHaveProperty('id');
    expect(response.body.title).toBe('Test Todo');
    expect(response.body.completed).toBe(false);
    todoId = response.body.id;
  });

  it('should return the created todo', async () => {
    const response = await request(app).get(`/todos/${todoId}`);
    expect(response.statusCode).toBe(200);
    expect(response.body.title).toBe('Test Todo');
    expect(response.body.completed).toBe(false);
  });

  it('should update the todo', async () => {
    const response = await request(app)
      .put(`/todos/${todoId}`)
      .send({ title: 'Updated Test Todo', completed: true });
    expect(response.statusCode).toBe(200);
    expect(response.body.title).toBe('Updated Test Todo');
    expect(response.body.completed).toBe(true);
  });

  it('should delete the todo', async () => {
    const response = await request(app).delete(`/todos/${todoId}`);
    expect(response.statusCode).toBe(204);

    const getResponse = await request(app).get(`/todos/${todoId}`);
    expect(getResponse.statusCode).toBe(404);
  });

  it('should return a 404 error for non-existent todo', async () => {
    const response = await request(app).get('/todos/nonexistent');
    expect(response.statusCode).toBe(404);
    expect(response.body.error).toBe('Todo not found');
  });

  it('should return a 400 error for invalid title on create', async () => {
    let response = await request(app)
      .post('/todos')
      .send({ title: '' });
    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Invalid title');

    response = await request(app)
      .post('/todos')
      .send({ title: 'a'.repeat(101) });
    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Invalid title');
  });

  it('should return a 400 error for invalid completed status on update', async () => {
    const response = await request(app)
      .put(`/todos/${todoId}`)
      .send({ completed: 'invalid' });
    expect(response.statusCode).toBe(400);
    expect(response.body.error).toBe('Invalid completed status');
  });

  it('should return a 500 error for unexpected server issues', async () => {
    // Simulate an error by accessing a non-existent property
    const response = await request(app)
      .get('/todos')
      .set('X-Error-Simulate', 'true');
    expect(response.statusCode).toBe(500);
  });
});

